-- Create "complaint_settings" table
CREATE TABLE `complaint_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `comments` bool NOT NULL DEFAULT true, `node_types` json NULL, `reasons` text NULL, `hide_after` int unsigned NOT NULL DEFAULT 3, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "complaint_targets" table
CREATE TABLE `complaint_targets` (`id` int unsigned NOT NULL AUTO_INCREMENT, `kind` varchar(16) NOT NULL, `object_id` int unsigned NOT NULL, `node_id` int unsigned NOT NULL, `author_id` int unsigned NOT NULL DEFAULT 0, `status` varchar(16) NOT NULL DEFAULT 'new', `hidden` bool NOT NULL DEFAULT false, `resolution` varchar(16) NOT NULL DEFAULT '', `resolved_by` int unsigned NOT NULL DEFAULT 0, `resolved_at` datetime NULL, `last_at` datetime NOT NULL, `created_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `uniq_complaint_targets_kind_object` (`kind`, `object_id`), INDEX `idx_complaint_targets_status_last` (`status`, `last_at`), INDEX `idx_complaint_targets_node` (`node_id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "complaints" table
CREATE TABLE `complaints` (`id` int unsigned NOT NULL AUTO_INCREMENT, `user_id` int unsigned NOT NULL, `reason` varchar(255) NOT NULL, `comment` varchar(1000) NOT NULL DEFAULT '', `created_at` datetime NOT NULL, `target_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `uniq_complaints_target_user` (`target_id`, `user_id`), INDEX `idx_complaints_user` (`user_id`), CONSTRAINT `complaints_complaint_targets_complaints` FOREIGN KEY (`target_id`) REFERENCES `complaint_targets` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
